import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const root = new URL('../', import.meta.url);
const compute = (items) => {
    const byCategory = {};
    for (const it of items) byCategory[it.category] = Math.round(((byCategory[it.category] ?? 0) + it.price * it.qty) * 100) / 100;
    const sorted = Object.fromEntries(Object.keys(byCategory).sort().map((k) => [k, byCategory[k]]));
    return { count: items.length, total: Math.round(items.reduce((s, it) => s + it.price * it.qty, 0) * 100) / 100, byCategory: sorted };
  };
const build = () => { const r = spawnSync(process.execPath, ['build.js'], { cwd: root, encoding: 'utf8' }); assert.equal(r.status, 0, r.stderr); return JSON.parse(readFileSync(new URL('../dist/out.json', import.meta.url), 'utf8')); };
test('matches the golden file', () => assert.deepEqual(readFileSync(new URL('../dist/out.json', import.meta.url), 'utf8'), readFileSync(new URL('../expected/out.json', import.meta.url), 'utf8')));
test('works on different data too', () => {
  const other = [
    { name: 'a', category: 'zeta', price: 0.1, qty: 3 },
    { name: 'b', category: 'alpha', price: 2, qty: 2 },
    { name: 'c', category: 'zeta', price: 0.2, qty: 1 },
    { name: 'd', category: 'mid', price: 10.005, qty: 1 },
    { name: 'e', category: 'alpha', price: 1.335, qty: 2 },
  ];
  writeFileSync(new URL('../data/items.json', import.meta.url), JSON.stringify(other, null, 2) + '\n');
