import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';

const round = (x) => Math.round(x * 100) / 100;
const items = JSON.parse(readFileSync(new URL('./data/items.json', import.meta.url), 'utf8'));
const byCategory = {};
for (const it of items) byCategory[it.category] = round((byCategory[it.category] ?? 0) + it.price * it.qty);
const out = {
  count: items.length,
  total: round(items.reduce((s, it) => s + it.price * it.qty, 0)),
  byCategory: Object.fromEntries(Object.keys(byCategory).sort().map((k) => [k, byCategory[k]])),
};
mkdirSync(new URL('./dist/', import.meta.url), { recursive: true });
writeFileSync(new URL('./dist/out.json', import.meta.url), JSON.stringify(out, null, 2) + '\n');
